package org.cas.client.platform.bar.web_srm;

/// Information received from WEB-SRM during a request of type Transaction
public class ResponseTransaction {

	/// Next test case number that you must execute.

	public String ProchainCasEssai;

	/// Transaction number generated by the SRS/POS

	public String NoTrans;

	/// Transaction number sent by the WEB-SRM

	public String PsiNoTrans;

	/// Date and time (hour, minute and second) the WEB-SRM processed the
	/// transaction

	public String PsiDatTrans;

	/// Date and hour the WEB-SRM the transaction batch was processed

	public String datLot;

	/// Number generated by the WEB-SRM identifying the batch of transactions

	public String noLot;

	/// Information received from WEB-SRM during a request of type Transaction

	/// <param name="ProchainCasEssai">Next test case number that you must
	/// execute.</param>
	/// <param name="NoTrans">Transaction number generated by the SRS/POS</param>
	/// <param name="PsiNoTrans">Transaction number sent by the WEB-SRM</param>
	/// <param name="PsiDatTrans">Date and hour the WEB-SRM processed the
	/// transaction</param>
	/// <param name="datLot">Date and hour the WEB-SRM the transaction batch was
	/// processed</param>
	/// <param name="noLot">Number generated by the WEB-SRM identifying the batch of
	/// transactions</param>
	public ResponseTransaction(String ProchainCasEssai, String NoTrans, String PsiNoTrans, String PsiDatTrans,
			String datLot, String noLot) {
		this.ProchainCasEssai = ProchainCasEssai;
		this.NoTrans = NoTrans;
		this.PsiNoTrans = PsiNoTrans;
		this.PsiDatTrans = PsiDatTrans;
		this.datLot = datLot;
		this.noLot = noLot;
	}

}
